// Codigo da esteira vem da URL: DELETE /api/esteiras/esteira6
msg.esteiraId = msg.req.params.esteiraId;
msg.topic = 'DELETE FROM esteiras WHERE codigo = ?';
msg.payload = [msg.esteiraId];
return msg;

// O no do MySQL devolve quantas linhas foram apagadas
var apagadas = (msg.payload && msg.payload.affectedRows) || 0;
if (apagadas === 0) {
    msg.statusCode = 404;
    msg.payload = { erro: 'Esteira ' + msg.esteiraId + ' nao encontrada' };
    return msg;
}
msg.statusCode = 200;
msg.payload = { status: 'esteira excluida', esteira: msg.esteiraId };
return msg;

var texto = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
msg.statusCode = 500;
msg.payload = { erro: 'Falha ao excluir esteira: ' + texto };
return msg;
